<?php /** @var \Illuminate\Database\Eloquent\Collection $repairs */ /** @var \Illuminate\Database\Eloquent\Collection $clients */ ?>
<?php if($receiptId): ?><script>open('./reparaciones/<?= $receiptId ?>','_blank')</script><?php endif ?>
<header class="page-head"><div><span class="eyebrow">SERVICIO TÉCNICO</span><h1>Reparaciones</h1><p>Controla entregas, pagos y vencimientos.</p></div><button class="btn btn-primary" onclick="document.querySelector('#new').open=true">+ Nueva reparación</button></header>
<details class="drawer card" id="new"><summary>Registrar reparación</summary><form class="panel grid grid-3" method="post" action="./reparaciones"><div class="field"><label>Cliente</label><select name="client_id" required><option value="">Seleccionar cliente</option><?php foreach($clients as $client): ?><option value="<?= $client->id ?>"><?= htmlspecialchars($client->name) ?></option><?php endforeach ?></select></div><div class="field"><label>Descripción</label><input name="description" required placeholder="Daño o servicio requerido"></div><div class="field"><label>Precio USD</label><input name="price" type="number" min="1" required placeholder="0"></div><button class="btn btn-primary">Registrar</button></form></details>
<section class="card table-wrap"><table class="data-table"><thead><tr><th>Cliente / reparación</th><th>Vence</th><th>Total Bs.</th><th>Saldo</th><th></th></tr></thead><tbody><?php foreach($repairs as $repair): ?><tr><td><strong><?= htmlspecialchars($repair->client->name) ?></strong><br><small><?= htmlspecialchars($repair->description) ?></small></td><td><?= $repair->due_date->format('d/m/Y') ?></td><td>Bs. <?= number_format((float)$repair->price_ves,2,',','.') ?></td><td>Bs. <?= number_format($repair->getRemainingAmountVes(),2,',','.') ?></td><td class="actions"><a class="btn btn-secondary btn-sm" target="_blank" href="./reparaciones/<?= $repair->id ?>">Comprobante</a><?php if($repair->getRemainingAmountVes()>0): ?><form method="post" action="./reparaciones/<?= $repair->id ?>/pagar" class="inline-form"><div class="field"><input name="amount_ves" type="number" min=".01" max="<?= $repair->getRemainingAmountVes() ?>" step=".01" required placeholder="Monto Bs."></div><select name="method" required><option value="Físico">Físico</option><option>Punto</option><option>Transferencia</option></select><button class="btn btn-primary btn-sm">Pagar</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></section>
